//! Parameter sets.  The concrete sets are generated by `examples/gen_params.rs`
//! (`cargo run --release --example gen_params`) into `params_generated.rs`.

use crate::fp::FpConfig;
use core::fmt::Debug;

pub trait ParamSet<const N: usize>: 'static + Copy + Clone + Send + Sync + Debug {
    const NAME: &'static str;
    /// Target classical security level in bits (NIST level 1/3/5 = 128/192/256).
    const LAMBDA: usize;
    type Cfg: FpConfig<N>;
    /// 2-power torsion exponent used by the scheme (p + 1 = 2^(E+1) 3^F3 c).
    const E: usize;
    /// d = 3^F3, the sender's isogeny degree.
    const F3: usize;
    /// Headroom of the secret degree f above p / 2^E.
    const KAPPA: usize;
    const COFACTOR: u64;
    /// Lower bound of the secret degree range [f_lo, 2 f_lo).
    const F_LO_HEX: &'static str;
    /// E_D : y^2 = x^3 + a4 x + a6 over F_p, j = -3375.
    const ED_A4_HEX: &'static str;
    const ED_A6_HEX: &'static str;
}

pub mod generated {
    include!("params_generated.rs");
}
pub use generated::*;
